from langchain.agents import create_agent
from langchain.agents.middleware import wrap_model_call
from langchain.chat_models import init_chat_model

cheap = init_chat_model("openai:gpt-4.1-mini")
strong = init_chat_model("anthropic:claude-sonnet-4-5")
@wrap_model_call
def route(request, handler):
    hard = len(request.messages) > 10 or "analyze" in str(request.messages[-1].content).lower()
    return handler(request.override(model=strong if hard else cheap))

