from langsmith import Client, tracing_context

def scrub(d: dict) -> dict:
    return {k: ("<hidden>" if k in {"messages", "input", "query"} else v) for k, v in d.items()}

client = Client(hide_inputs=scrub, hide_outputs=scrub)

